def three_feed_common(a, b, c):
    nb, nc = len(b), len(c)
    prev = [[0] * (nc + 1) for _ in range(nb + 1)]
    for x in a:
        cur = [[0] * (nc + 1)]
        for j in range(1, nb + 1):
            y = b[j - 1]
            up, diag, left = prev[j], prev[j - 1], cur[j - 1]
            row = [0]
            for k in range(1, nc + 1):
                if x == y == c[k - 1]:
                    row.append(diag[k - 1] + 1)
                else:
                    row.append(max(up[k], left[k], row[k - 1]))
            cur.append(row)
        prev = cur
    return prev[nb][nc]

